/* GENERATED FILE — do not edit. Source: spec/. Run: pnpm gen */

@layer components {
  .ew-dialog {
    /* anatomy: root, backdrop, frame, header, body, footer, close */
  }
  .ew-dialog {
    border: var(--ew-structure-dialog-border-width, 1px) var(--ew-structure-dialog-border-style, solid) var(--ew-color-border-strong, #888);
    border-radius: var(--ew-structure-dialog-radius, var(--ew-dialog-radius, 12px));
    clip-path: var(--ew-structure-dialog-clip, none);
    padding: var(--ew-dialog-padding, 24px);
    max-width: var(--ew-dialog-max-width, 420px);
    width: calc(100% - 32px);
    background: var(--ew-color-bg-elevated, #fff);
    color: var(--ew-color-fg-default, inherit);
    box-shadow: var(--ew-structure-dialog-shadow, var(--ew-elevation-dialog, none));
    font-family: var(--ew-font-body, system-ui, sans-serif);
  }
  .ew-dialog::backdrop { background: var(--ew-color-overlay, rgb(0 0 0 / 0.45)); }
  .ew-dialog__header h2 {
    margin: 0 0 12px;
    font-family: var(--ew-font-display, inherit);
    letter-spacing: var(--ew-structure-card-title-tracking, 0);
  }
  .ew-dialog__body { margin: 0; }
  .ew-dialog__footer { display: flex; gap: 8px; justify-content: flex-end; margin-top: 16px; flex-wrap: wrap; }
  .ew-dialog__close {
    position: absolute;
    top: 12px;
    inset-inline-end: 12px;
  }
  .ew-dialog--sm, .ew-dialog[data-size="sm"] { max-width: min(320px, calc(100vw - 32px)); }
  .ew-dialog--md, .ew-dialog[data-size="md"] { max-width: min(420px, calc(100vw - 32px)); }
  .ew-dialog--lg, .ew-dialog[data-size="lg"] { max-width: min(720px, calc(100vw - 32px)); }
  @media (max-width: 600px) {
    .ew-dialog--fullscreen-mobile, .ew-dialog[data-size="fullscreen-mobile"] {
      width: 100%;
      max-width: 100%;
      max-height: min(92vh, 100%);
      margin: auto 0 0;
      border-end-start-radius: 0;
      border-end-end-radius: 0;
    }
  }
  @media (prefers-reduced-motion: reduce) {
    .ew-dialog, .ew-dialog::backdrop { transition: none; }
  }
  /* spec variant variant=modal */
  .ew-dialog[data-variant="modal"] { --ew-spec-variant-variant: modal; }
  /* spec variant variant=sheet */
  .ew-dialog[data-variant="sheet"] { --ew-spec-variant-variant: sheet; }
  .ew-dialog:not([data-variant]) { --ew-spec-variant-variant: modal; }
  .ew-dialog[data-size="sm"] { --ew-spec-size: sm; }
  .ew-dialog[data-size="md"] { --ew-spec-size: md; }
  .ew-dialog[data-size="lg"] { --ew-spec-size: lg; }
  .ew-dialog:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-dialog, .ew-dialog *, .ew-dialog *::before, .ew-dialog *::after {
      transition: none !important;
      animation: none !important;
    }
  }
}
